shell_commands:
python3 - <<'EOF'
p='src/transport/conversationList.acceptance.test.ts'
s=open(p).read()
start=s.index("    const refused = ")
end=s.index("  it(\"answers with the connection's")
new='''    const answer = (frame: Record<string, unknown>): string => {
      const result = validateMessage({type: 'list_conversations', ...frame});
      return result.valid ? 'valid' : result.error;
    };
    const cursor = {updatedAt: '2026-11-02T08:00:00.000Z', sessionId: 'c-mid'};
    const namesLimit = expect.stringMatching(/limit/);
    const namesBefore = expect.stringMatching(/before/);

    expect({
      bare: answer({}),
      paged: answer({limit: 10, before: cursor}),
      limitZero: answer({limit: 0}),
      limitTooMany: answer({limit: 201}),
      limitFraction: answer({limit: 1.5}),
      limitString: answer({limit: '10'}),
      beforeNotADate: answer({before: {updatedAt: 'not a date', sessionId: 'c-mid'}}),
      beforeHalfACursor: answer({before: {updatedAt: cursor.updatedAt}}),
    }).toEqual({
      bare: 'valid',
      paged: 'valid',
      limitZero: namesLimit,
      limitTooMany: namesLimit,
      limitFraction: namesLimit,
      limitString: namesLimit,
      beforeNotADate: namesBefore,
      beforeHalfACursor: namesBefore,
    });
  });

'''
s=s[:start]+new+s[end:]
open(p,'w').write(s)
EOF
npx prettier --write src/transport/conversationList.acceptance.test.ts && npm test -- src/transport/conversationList.acceptance.test.ts 2>&1 | tail -150

python3 - <<'EOF'
p='src/transport/conversationList.acceptance.test.ts'
s=open(p).read()
old="  for (const hal of servers.splice(0)) await hal.stop();"
new="""  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await waitFor(() => wss.clients.size === 0);
    await hal.stop();
  }"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF
npx prettier --write src/transport/conversationList.acceptance.test.ts >/dev/null && npm test -- src/transport/conversationList.acceptance.test.ts 2>&1 | head -60; npm test -- src/transport/conversationList.acceptance.test.ts 2>&1 | grep -c "Cannot log"
